"use strict";(globalThis.webpackChunkdocusaurus_root=globalThis.webpackChunkdocusaurus_root||[]).push([[7034],{7080:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/Specdriven-development/docs/intro","label":"Introduction","docId":"intro","unlisted":false},{"type":"link","href":"/Specdriven-development/docs/schedule","label":"Course Schedule","docId":"schedule","unlisted":false},{"type":"link","href":"/Specdriven-development/docs/hardware","label":"Hardware Requirements","docId":"hardware","unlisted":false},{"type":"link","href":"/Specdriven-development/docs/assessments","label":"Assessments","docId":"assessments","unlisted":false},{"type":"category","label":"modules","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/Specdriven-development/docs/modules/nervous-system","label":"Module 1 - The Nervous System","docId":"modules/nervous-system","unlisted":false},{"type":"link","href":"/Specdriven-development/docs/modules/digital-twin","label":"Module 2 - The Digital Twin","docId":"modules/digital-twin","unlisted":false},{"type":"link","href":"/Specdriven-development/docs/modules/ai-robot-brain","label":"Module 3 - The AI-Robot Brain","docId":"modules/ai-robot-brain","unlisted":false},{"type":"link","href":"/Specdriven-development/docs/modules/vla","label":"Module 4 - Vision-Language-Action","docId":"modules/vla","unlisted":false}]}]},"docs":{"assessments":{"id":"assessments","title":"Assessments","description":"Students will be evaluated through a series of practical projects demonstrating their mastery of Physical AI concepts.","sidebar":"tutorialSidebar"},"hardware":{"id":"hardware","title":"Hardware Requirements","description":"This course is technically demanding. It sits at the intersection of three heavy computational loads: Physics Simulation (Isaac Sim/Gazebo), Visual Perception (SLAM/Computer Vision), and Generative AI (LLMs/VLA).","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Introduction","description":"Comprehensive overview of Physical AI & Humanoid Robotics course focusing on embodied intelligence.","sidebar":"tutorialSidebar"},"modules/ai-robot-brain":{"id":"modules/ai-robot-brain","title":"Module 3 - The AI-Robot Brain","description":"At the heart of every intelligent Physical AI system lies a sophisticated \\"brain\\" capable of processing complex sensory data, making informed decisions, and executing precise motor commands. This module delves into the deep learning architectures and advanced AI techniques that empower robots, particularly humanoids, to perceive their surroundings, understand their state, and interact intelligently with the physical world. We will explore how to develop the cognitive capabilities that transform a mechanical body into an autonomous, adaptive agent.","sidebar":"tutorialSidebar"},"modules/digital-twin":{"id":"modules/digital-twin","title":"Module 2 - The Digital Twin","description":"Developing and testing Physical AI systems, especially humanoid robots, in the real world can be resource-intensive, time-consuming, and even risky. This is where the concept of a \\"Digital Twin\\" becomes indispensable. A digital twin is a virtual replica of a physical system, allowing for comprehensive simulation and testing in a safe, controlled, and reproducible environment. This module dives deep into creating and leveraging such digital twins using powerful simulation platforms.","sidebar":"tutorialSidebar"},"modules/nervous-system":{"id":"modules/nervous-system","title":"Module 1 - The Nervous System","description":"In the realm of Physical AI and Humanoid Robotics, effective communication and control are paramount. Just as a biological nervous system coordinates actions and transmits sensory information throughout a body, a robot requires a robust and flexible middleware to manage its complex array of sensors, actuators, and intelligent processing units. This module introduces you to the Robot Operating System 2 (ROS 2), the industry-standard framework that serves as the \\"nervous system\\" for modern robotic platforms.","sidebar":"tutorialSidebar"},"modules/vla":{"id":"modules/vla","title":"Module 4 - Vision-Language-Action","description":"The pinnacle of embodied intelligence lies in a robot\'s ability to understand and respond to human intent expressed through natural language, perceive its environment, and execute complex physical actions. This module explores the groundbreaking paradigm of Vision-Language-Action (VLA), where Large Language Models (LLMs) are integrated with robotic systems to enable intuitive and highly capable human-robot interaction. You will discover how to bridge the gap between abstract human commands and concrete robotic movements, paving the way for truly intelligent autonomous agents.","sidebar":"tutorialSidebar"},"schedule":{"id":"schedule","title":"Course Schedule","description":"Weeks 1-2: Introduction to Physical AI","sidebar":"tutorialSidebar"}}}}')}}]);